insert into decks (id, title, subject, grade_level, description, bncc_codes, sources, review_status) values ('ef2-cie-lua-energia', 'Lua, eclipses e energia', 'science', 'elementary_2'::grade_band, 'Fases da Lua e eclipses pelas posições de Sol, Terra e Lua; fontes de energia renováveis e não renováveis; consumo elétrico.', array['EF08CI01', 'EF08CI04', 'EF08CI12']::text[], '[{"name":"BNCC — Base Nacional Comum Curricular (MEC)","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","license":"Documento público oficial","usage":"Alinhamento dos temas às habilidades EF08CI01, EF08CI04 e EF08CI12"},{"name":"Redação própria do projeto (rascunho assistido por IA)","license":"Conteúdo original","usage":"Texto dos cards, a partir de conteúdo escolar consolidado. Precisa de revisão de um professor antes de aprovar."}]'::jsonb, 'pending_review'::content_review_status)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-cie-lua-energia-01', 'ef2-cie-lua-energia', 1, 'multiple_choice'::card_kind, 'Em qual fase a Lua está entre a Terra e o Sol?', 'Na Lua nova, a face iluminada da Lua fica voltada para o Sol, e não a vemos da Terra.', array['Lua cheia', 'Lua nova', 'Quarto crescente', 'Quarto minguante']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-cie-lua-energia-02', 'ef2-cie-lua-energia', 2, 'multiple_choice'::card_kind, 'Um eclipse lunar acontece quando…', 'No eclipse lunar, a sombra da Terra cobre a Lua. Por isso ele só ocorre na Lua cheia.', array['a Lua fica entre o Sol e a Terra', 'a Terra fica entre o Sol e a Lua', 'o Sol fica entre a Terra e a Lua', 'a Lua se afasta da Terra']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-cie-lua-energia-03', 'ef2-cie-lua-energia', 3, 'multiple_choice'::card_kind, 'Em qual fase da Lua um eclipse solar pode acontecer?', 'O eclipse solar exige a Lua entre a Terra e o Sol, o que só ocorre na Lua nova.', array['Lua cheia', 'Quarto crescente', 'Lua nova', 'Quarto minguante']::text[], 2, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-cie-lua-energia-04', 'ef2-cie-lua-energia', 4, 'short_answer'::card_kind, 'Aproximadamente quantos dias dura o ciclo completo das fases da Lua?', 'Cerca de 29,5 dias (mês sinódico).', null, null, array['29,5', '29,5 dias', '29', '29 dias', '30', '30 dias']::text[])
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-cie-lua-energia-05', 'ef2-cie-lua-energia', 5, 'multiple_choice'::card_kind, 'Na Lua cheia, onde a Lua está?', 'Com a Terra entre o Sol e a Lua (mas fora da sombra), vemos toda a face iluminada.', array['Do lado oposto ao Sol, em relação à Terra', 'Entre a Terra e o Sol', 'Ao lado do Sol', 'Atrás do Sol']::text[], 0, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-cie-lua-energia-06', 'ef2-cie-lua-energia', 6, 'open'::card_kind, 'Por que vemos a Lua em fases diferentes ao longo do mês?', 'A Lua não tem luz própria e sempre tem metade iluminada pelo Sol. Enquanto ela orbita a Terra, vemos partes diferentes dessa metade iluminada. As fases NÃO são causadas pela sombra da Terra.', null, null, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-cie-lua-energia-07', 'ef2-cie-lua-energia', 7, 'open'::card_kind, 'Se a Lua passa entre a Terra e o Sol a cada Lua nova, por que não acontece um eclipse solar todo mês?', 'A órbita da Lua é inclinada (cerca de 5°) em relação à órbita da Terra. Na maioria das luas novas, a Lua passa um pouco acima ou abaixo do alinhamento Sol–Terra.', null, null, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-cie-lua-energia-08', 'ef2-cie-lua-energia', 8, 'multiple_choice'::card_kind, 'Qual destas é uma fonte de energia renovável?', 'A energia solar se renova continuamente. Petróleo, carvão e gás natural são fósseis e levam milhões de anos para se formar.', array['Petróleo', 'Carvão mineral', 'Gás natural', 'Energia solar']::text[], 3, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-cie-lua-energia-09', 'ef2-cie-lua-energia', 9, 'multiple_choice'::card_kind, 'Qual é a principal fonte de geração de eletricidade no Brasil?', 'As hidrelétricas respondem pela maior parte da eletricidade gerada no Brasil.', array['Nuclear', 'Hidrelétrica', 'Carvão', 'Petróleo']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-cie-lua-energia-10', 'ef2-cie-lua-energia', 10, 'multiple_choice'::card_kind, 'A energia eólica é obtida a partir…', 'Turbinas eólicas transformam o movimento do vento em energia elétrica.', array['do calor do interior da Terra', 'do vento', 'das marés', 'da queima de biomassa']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-cie-lua-energia-11', 'ef2-cie-lua-energia', 11, 'short_answer'::card_kind, 'Um chuveiro de 5 000 W fica ligado por 2 horas. Quantos kWh ele consome?', '5 000 W = 5 kW; 5 kW × 2 h = 10 kWh.', null, null, array['10', '10 kwh', '10kwh']::text[])
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-cie-lua-energia-12', 'ef2-cie-lua-energia', 12, 'open'::card_kind, 'Uma fonte de energia renovável é sempre livre de impacto ambiental? Justifique com um exemplo.', 'Não. "Renovável" diz respeito à reposição da fonte, não à ausência de impacto. Exemplos: hidrelétricas alagam grandes áreas e afetam ecossistemas e comunidades, e parques eólicos podem afetar aves e a paisagem.', null, null, null)
insert into decks (id, title, subject, grade_level, description, bncc_codes, sources, review_status) values ('ef2-his-revolucoes', 'Iluminismo, revoluções e o Brasil de 1808', 'history', 'elementary_2'::grade_band, 'Ideias iluministas, Revolução Francesa, Revolução Industrial e a chegada da Corte portuguesa até a Independência.', array['EF08HI01', 'EF08HI03', 'EF08HI04', 'EF08HI12']::text[], '[{"name":"BNCC — Base Nacional Comum Curricular (MEC)","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","license":"Documento público oficial","usage":"Alinhamento dos temas às habilidades EF08HI01, EF08HI03, EF08HI04 e EF08HI12"},{"name":"Redação própria do projeto (rascunho assistido por IA)","license":"Conteúdo original","usage":"Texto dos cards, a partir de conteúdo escolar consolidado. Precisa de revisão de um professor antes de aprovar."}]'::jsonb, 'pending_review'::content_review_status)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-01', 'ef2-his-revolucoes', 1, 'multiple_choice'::card_kind, 'Qual ideia é associada ao pensador iluminista Montesquieu?', 'Em "O Espírito das Leis", Montesquieu defendeu dividir o poder para evitar abusos.', array['Separação dos poderes em Executivo, Legislativo e Judiciário', 'Direito divino dos reis', 'Mercantilismo', 'Monarquia absoluta']::text[], 0, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-02', 'ef2-his-revolucoes', 2, 'multiple_choice'::card_kind, 'Qual era o lema da Revolução Francesa?', '"Liberdade, Igualdade, Fraternidade" resumia os ideais revolucionários.', array['Ordem e Progresso', 'Liberdade, Igualdade, Fraternidade', 'Deus, Pátria, Família', 'Paz, Pão e Terra']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-03', 'ef2-his-revolucoes', 3, 'short_answer'::card_kind, 'Em que ano começou a Revolução Francesa, marcada pela queda da Bastilha?', 'Em 1789, com a tomada da Bastilha em 14 de julho.', null, null, array['1789']::text[])
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-04', 'ef2-his-revolucoes', 4, 'multiple_choice'::card_kind, 'Antes da Revolução Francesa, quem formava o Terceiro Estado?', 'O Terceiro Estado reunia a maioria da população e pagava a maior parte dos impostos.', array['O clero', 'A nobreza', 'A burguesia, os camponeses e os trabalhadores urbanos', 'Apenas o rei e sua família']::text[], 2, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-05', 'ef2-his-revolucoes', 5, 'multiple_choice'::card_kind, 'Qual documento de 1789 afirmava que "os homens nascem e são livres e iguais em direitos"?', 'A Declaração dos Direitos do Homem e do Cidadão foi aprovada pela Assembleia francesa em 1789.', array['Declaração dos Direitos do Homem e do Cidadão', 'Constituição dos Estados Unidos', 'Carta Magna', 'Tratado de Tordesilhas']::text[], 0, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-06', 'ef2-his-revolucoes', 6, 'multiple_choice'::card_kind, 'Em qual país começou a Revolução Industrial?', 'Ela começou na Inglaterra, na segunda metade do século XVIII.', array['França', 'Inglaterra', 'Estados Unidos', 'Alemanha']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-07', 'ef2-his-revolucoes', 7, 'multiple_choice'::card_kind, 'Qual invenção foi central na primeira fase da Revolução Industrial?', 'A máquina a vapor movimentou fábricas têxteis, trens e navios.', array['Motor a combustão', 'Máquina a vapor', 'Energia elétrica', 'Computador']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-08', 'ef2-his-revolucoes', 8, 'short_answer'::card_kind, 'Em que ano a família real portuguesa chegou ao Brasil?', 'Em 1808, fugindo das tropas de Napoleão.', null, null, array['1808']::text[])
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-09', 'ef2-his-revolucoes', 9, 'multiple_choice'::card_kind, 'Qual medida Dom João tomou logo ao chegar ao Brasil em 1808?', 'A abertura dos portos encerrou o monopólio comercial de Portugal sobre o Brasil.', array['A abolição da escravidão', 'A abertura dos portos às nações amigas', 'A proclamação da República', 'A independência do Brasil']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-10', 'ef2-his-revolucoes', 10, 'short_answer'::card_kind, 'Quem proclamou a Independência do Brasil em 1822?', 'Dom Pedro I, em 7 de setembro de 1822.', null, null, array['Dom Pedro', 'Dom Pedro I', 'D. Pedro I', 'Pedro I', 'D Pedro']::text[])
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-11', 'ef2-his-revolucoes', 11, 'open'::card_kind, 'Por que as ideias iluministas ameaçavam o poder dos reis absolutistas?', 'Os iluministas defendiam a razão, a liberdade individual, a igualdade perante a lei e a divisão dos poderes. Isso questionava o direito divino e o poder concentrado nas mãos do rei.', null, null, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-12', 'ef2-his-revolucoes', 12, 'open'::card_kind, 'Como a Revolução Industrial mudou a vida dos trabalhadores?', 'Muitos trabalhadores migraram do campo para as cidades. Nas fábricas, enfrentavam jornadas muito longas, salários baixos, trabalho infantil e condições insalubres. Isso levou ao surgimento de movimentos operários e sindicatos.', null, null, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-his-revolucoes-13', 'ef2-his-revolucoes', 13, 'open'::card_kind, 'Por que a chegada da Corte portuguesa em 1808 é vista como um passo rumo à independência do Brasil?', 'O Brasil virou sede do império português: os portos foram abertos, surgiram instituições como o Banco do Brasil e a Imprensa Régia, e em 1815 o Brasil foi elevado a Reino Unido. Quando a Corte voltou a Portugal, as elites resistiram a retornar à condição de colônia.', null, null, null)
insert into decks (id, title, subject, grade_level, description, bncc_codes, sources, review_status) values ('ef2-mat-potencias', 'Potências e notação científica', 'math', 'elementary_2'::grade_band, 'Propriedades das potências, expoentes negativos, raízes como potências e notação científica.', array['EF08MA01', 'EF08MA02']::text[], '[{"name":"BNCC — Base Nacional Comum Curricular (MEC)","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","license":"Documento público oficial","usage":"Alinhamento dos temas às habilidades EF08MA01 e EF08MA02"},{"name":"Redação própria do projeto (rascunho assistido por IA)","license":"Conteúdo original","usage":"Texto dos cards, a partir de conteúdo escolar consolidado. Precisa de revisão de um professor antes de aprovar."}]'::jsonb, 'pending_review'::content_review_status)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-01', 'ef2-mat-potencias', 1, 'multiple_choice'::card_kind, 'Quanto vale 2⁻³?', 'Expoente negativo inverte a base: 2⁻³ = 1/2³ = 1/8.', array['−8', '1/8', '−1/8', '8']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-02', 'ef2-mat-potencias', 2, 'short_answer'::card_kind, 'Quanto vale 10⁰?', 'Todo número diferente de zero elevado a zero vale 1.', null, null, array['1', 'um']::text[])
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-03', 'ef2-mat-potencias', 3, 'multiple_choice'::card_kind, 'Qual é o resultado de 5³ · 5²?', 'Na multiplicação de potências de mesma base, conservamos a base e somamos os expoentes: 5³⁺² = 5⁵.', array['5⁶', '5⁵', '25⁵', '10⁵']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-04', 'ef2-mat-potencias', 4, 'multiple_choice'::card_kind, 'Qual é o resultado de (3²)³?', 'Potência de potência: multiplicamos os expoentes, (3²)³ = 3²ˣ³ = 3⁶.', array['3⁵', '3⁶', '9⁶', '3⁸']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-05', 'ef2-mat-potencias', 5, 'short_answer'::card_kind, 'Calcule 7⁸ ÷ 7⁶ e escreva o resultado como um número.', 'Divisão de mesma base: subtraímos os expoentes, 7⁸⁻⁶ = 7² = 49.', null, null, array['49']::text[])
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-06', 'ef2-mat-potencias', 6, 'multiple_choice'::card_kind, 'Como escrever 45 000 000 em notação científica?', 'Na notação científica o primeiro fator fica entre 1 e 10: 45 000 000 = 4,5 × 10⁷.', array['45 × 10⁶', '4,5 × 10⁷', '4,5 × 10⁶', '0,45 × 10⁸']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-07', 'ef2-mat-potencias', 7, 'multiple_choice'::card_kind, 'Quanto é 3,2 × 10⁻⁴ na forma decimal?', '10⁻⁴ desloca a vírgula 4 casas para a esquerda: 3,2 × 10⁻⁴ = 0,00032.', array['0,0032', '0,00032', '0,000032', '32 000']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-08', 'ef2-mat-potencias', 8, 'short_answer'::card_kind, 'Quanto vale (−2)⁴?', '(−2)·(−2)·(−2)·(−2) = 16. Base negativa com expoente par dá resultado positivo.', null, null, array['16']::text[])
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-09', 'ef2-mat-potencias', 9, 'multiple_choice'::card_kind, 'Qual destas está escrita corretamente em notação científica?', 'O primeiro fator precisa ser maior ou igual a 1 e menor que 10. Só 7,1 × 10⁵ cumpre essa regra.', array['12 × 10³', '0,5 × 10²', '7,1 × 10⁵', '10 × 10⁴']::text[], 2, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-10', 'ef2-mat-potencias', 10, 'multiple_choice'::card_kind, '√7 pode ser escrito como qual potência?', 'A raiz quadrada é uma potência de expoente 1/2: √7 = 7^(1/2).', array['7²', '7^(1/2)', '7⁻²', '1/7']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-11', 'ef2-mat-potencias', 11, 'open'::card_kind, 'Por que qualquer número diferente de zero elevado a zero vale 1? Use a divisão de potências de mesma base para explicar.', 'aⁿ ÷ aⁿ = aⁿ⁻ⁿ = a⁰. Mas qualquer número diferente de zero dividido por ele mesmo é 1. Então a⁰ = 1.', null, null, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-12', 'ef2-mat-potencias', 12, 'open'::card_kind, 'Explique por que 2⁻¹ é igual a 1/2.', 'Seguindo o padrão 2² = 4, 2¹ = 2, 2⁰ = 1: cada vez que o expoente diminui 1, dividimos por 2. Então 2⁻¹ = 1 ÷ 2 = 1/2.', null, null, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-mat-potencias-13', 'ef2-mat-potencias', 13, 'open'::card_kind, 'A distância média da Terra ao Sol é de cerca de 150 000 000 km. Como escrever esse número em notação científica, e por que essa forma é útil?', '1,5 × 10⁸ km. A notação científica facilita ler, comparar ordens de grandeza e fazer contas com números muito grandes ou muito pequenos.', null, null, null)
insert into decks (id, title, subject, grade_level, description, bncc_codes, sources, review_status) values ('ef2-por-oracao-figuras', 'Oração, vozes verbais e figuras de linguagem', 'language', 'elementary_2'::grade_band, 'Sujeito e complementos verbais, voz ativa e passiva, e as principais figuras de linguagem.', array['EF08LP06', 'EF08LP07', 'EF08LP08', 'EF69LP54']::text[], '[{"name":"BNCC — Base Nacional Comum Curricular (MEC)","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","license":"Documento público oficial","usage":"Alinhamento dos temas às habilidades EF08LP06, EF08LP07, EF08LP08 e EF69LP54"},{"name":"Redação própria do projeto (rascunho assistido por IA)","license":"Conteúdo original","usage":"Texto dos cards, a partir de conteúdo escolar consolidado. Precisa de revisão de um professor antes de aprovar."}]'::jsonb, 'pending_review'::content_review_status)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-01', 'ef2-por-oracao-figuras', 1, 'multiple_choice'::card_kind, 'Em "Os alunos organizaram a feira de ciências", qual é o sujeito?', '"Os alunos" é o termo sobre o qual se declara algo e concorda com o verbo.', array['Os alunos', 'organizaram', 'a feira de ciências', 'de ciências']::text[], 0, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-02', 'ef2-por-oracao-figuras', 2, 'multiple_choice'::card_kind, 'Em "O bolo foi feito pela avó", o verbo está em qual voz?', 'Voz passiva analítica: o sujeito (o bolo) sofre a ação, e "pela avó" é o agente da passiva.', array['Voz ativa', 'Voz passiva', 'Voz reflexiva', 'Não tem voz verbal']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-03', 'ef2-por-oracao-figuras', 3, 'short_answer'::card_kind, 'Passe para a voz ativa: "A carta foi escrita por Marina."', 'Marina escreveu a carta. (O agente da passiva vira o sujeito.)', null, null, array['Marina escreveu a carta', 'Marina escreveu a carta.']::text[])
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-04', 'ef2-por-oracao-figuras', 4, 'multiple_choice'::card_kind, 'Em "Gosto de música", o termo "de música" é…', '"Gostar" pede preposição (gostar DE algo), então o complemento é objeto indireto.', array['objeto direto', 'objeto indireto', 'sujeito', 'predicativo']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-05', 'ef2-por-oracao-figuras', 5, 'multiple_choice'::card_kind, 'Em "Comprei pão", o termo "pão" é…', '"Comprar" liga-se ao complemento sem preposição, então "pão" é objeto direto.', array['objeto direto', 'objeto indireto', 'sujeito', 'adjunto adverbial']::text[], 0, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-06', 'ef2-por-oracao-figuras', 6, 'multiple_choice'::card_kind, 'Qual figura de linguagem aparece em "Ele é forte como um touro"?', 'É uma comparação (símile), marcada pelo conectivo "como".', array['Metáfora', 'Comparação', 'Hipérbole', 'Ironia']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-07', 'ef2-por-oracao-figuras', 7, 'multiple_choice'::card_kind, 'Qual figura de linguagem aparece em "Já te falei isso um milhão de vezes!"?', 'Hipérbole: um exagero intencional para dar ênfase.', array['Eufemismo', 'Metonímia', 'Hipérbole', 'Antítese']::text[], 2, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-08', 'ef2-por-oracao-figuras', 8, 'multiple_choice'::card_kind, 'Qual figura de linguagem aparece em "O vento sussurrava segredos"?', 'Personificação (prosopopeia): atribuir uma ação humana, sussurrar, a um ser inanimado.', array['Personificação', 'Comparação', 'Paradoxo', 'Eufemismo']::text[], 0, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-09', 'ef2-por-oracao-figuras', 9, 'short_answer'::card_kind, 'Qual figura de linguagem aparece em "Aquele menino é uma fera no futebol"?', 'Metáfora: uma comparação implícita, sem conectivo.', null, null, array['metáfora', 'metafora']::text[])
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-10', 'ef2-por-oracao-figuras', 10, 'multiple_choice'::card_kind, 'Qual figura de linguagem aparece em "Li Machado de Assis nas férias"?', 'Metonímia: o autor é citado no lugar da obra dele.', array['Metáfora', 'Metonímia', 'Hipérbole', 'Ironia']::text[], 1, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-11', 'ef2-por-oracao-figuras', 11, 'open'::card_kind, 'Qual é a diferença entre comparação e metáfora? Dê um exemplo de cada.', 'A comparação usa um conectivo explícito (como, tal qual): "Seus olhos brilham como estrelas". A metáfora é uma comparação implícita, sem conectivo: "Seus olhos são estrelas".', null, null, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-12', 'ef2-por-oracao-figuras', 12, 'open'::card_kind, 'Uma notícia diz "Três pessoas foram resgatadas". Por que o jornal poderia preferir a voz passiva aqui? Que efeito de sentido isso cria?', 'A voz passiva coloca em destaque quem sofreu a ação (as pessoas resgatadas) e permite omitir ou deixar em segundo plano quem fez o resgate.', null, null, null)
insert into cards (id, deck_id, position, kind, prompt, answer, choices, correct_choice, accepted_answers) values ('ef2-por-oracao-figuras-13', 'ef2-por-oracao-figuras', 13, 'open'::card_kind, 'Em "Choveu muito ontem", qual é o sujeito? Explique.', 'É uma oração sem sujeito: "chover" é um verbo impessoal que indica fenômeno da natureza, e não há um ser a quem atribuir a ação.', null, null, null)
